(() => {
  const GEO_URL = "/economic_geography_103_simplified.geojson";
  const HAZARD_PAYLOAD_B64 = "";
  const PERIODS = [
    ["P1_BASELINE_2006_2025","P1 · Climate reference 2006–2025"],
    ["P2_NEAR_2026_2050","P2 · Near term 2026–2050"],
    ["P3_MID_2051_2075","P3 · Mid century 2051–2075"],
    ["P4_COMMON_2076_2099","P4 · Far future 2076–2099"],
  ];
  const CONTEXTS = {WBGT_id:"Indoor / shade proxy", WBGT_od:"Direct-sun proxy"};
  const THRESHOLDS=[25,26,27,28];
  const IMPACT_SCALE=[[0,"#ffffcc"],[.2,"#ffeda0"],[.4,"#fed976"],[.6,"#feb24c"],[.8,"#f03b20"],[1,"#bd0026"]];
  const DIVERGING_SCALE=[[0,"#2166ac"],[.25,"#92c5de"],[.5,"#f7f7f7"],[.75,"#f4a582"],[1,"#b2182b"]];

  let hzGeo=null, records=[], provinces=[];
  const el=id=>document.getElementById(id);
  const n=x=>Number(x||0);
  const f=(x,d=1)=>n(x).toLocaleString("en-US",{minimumFractionDigits:d,maximumFractionDigits:d});
  const displayProvince=x=>({LAquila:"L'Aquila","Reggio nellEmilia":"Reggio nell'Emilia","Forli Cesena":"Forlì-Cesena","Valle dAosta Vallee dAoste":"Valle d'Aosta/Vallée d'Aoste","Massa Carrara":"Massa-Carrara","Pesaro e Urbino":"Pesaro-Urbino","Verbano Cusio Ossola":"Verbano-Cusio-Ossola"}[x]||x);

  async function fetchText(url){const r=await fetch(url,{cache:"no-store"});if(!r.ok)throw new Error(`${url}: ${r.status}`);return r.text();}
  async function fetchJson(url){const r=await fetch(url,{cache:"no-store"});if(!r.ok)throw new Error(`${url}: ${r.status}`);return r.json();}
  async function loadPayload(){
    const b64=HAZARD_PAYLOAD_B64;
    const bin=atob(b64), bytes=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
    const ds=new DecompressionStream("gzip");
    const txt=await new Response(new Blob([bytes]).stream().pipeThrough(ds)).text();
    return JSON.parse(txt);
  }
  function percentile(values,q){const a=values.filter(Number.isFinite).sort((x,y)=>x-y);if(!a.length)return 0;const pos=(a.length-1)*q,lo=Math.floor(pos),hi=Math.ceil(pos);return lo===hi?a[lo]:a[lo]+(a[hi]-a[lo])*(pos-lo);}
  function bounds(values,mode,fixedValues=null){let a=(mode==="fixed"&&fixedValues?.length?fixedValues:values).filter(Number.isFinite);if(!a.length)return[0,1];let lo,hi;if(mode==="adaptive"){lo=percentile(a,.05);hi=percentile(a,.95);}else{lo=Math.min(...a);hi=Math.max(...a);}if(!(hi>lo)){const pad=Math.abs(lo)*.05||1;lo-=pad;hi+=pad;}return[lo,hi];}

  function addUi(){
    if(document.querySelector('[data-view="hazard"]'))return;
    const nav=document.querySelector("nav.tabs");if(!nav)return;
    const btn=document.createElement("button");btn.className="tab";btn.dataset.view="hazard";btn.textContent="Climate hazard";
    nav.insertBefore(btn,nav.querySelector('[data-view="workforce"]')||nav.querySelector('[data-view="uncertainty"]')||null);
    const section=document.createElement("section");section.id="hazard";section.className="view hidden";
    section.innerHTML=`
      <div class="filters card">
        <label>Climate period<select id="hz-period"></select></label>
        <label>Exposure context<select id="hz-context"></select></label>
        <label>WBGT threshold<select id="hz-threshold"></select></label>
        <label>Map outcome<select id="hz-outcome"><option value="delta">Additional days/year vs P1</option><option value="absolute">Absolute days/year</option></select></label>
        <label>Province profile<select id="hz-province"></select></label>
        <label>Colour scaling<select id="hz-color"><option value="adaptive">Adaptive · 5th–95th percentile</option><option value="visible">Visible range · min–max</option><option value="fixed">Fixed · same scale across P1–P4</option></select></label>
      </div>
      <div class="card prose compact">
        <p><strong>Thermal hazard before the economic model.</strong> The indicator counts days/year when area-weighted provincial daily WBGT exceeds the selected threshold. Future-minus-baseline changes are paired within each of the same 10 climate-model chains before ensemble aggregation.</p>
        <p class="hint">The direct-sun view uses the project's simplified outdoor proxy and should not be read as instrument-measured full outdoor WBGT. P4 is the common 2076–2099 ten-run horizon.</p>
      </div>
      <div class="kpis">
        <div class="kpi"><span>Median province</span><strong id="hz-kpi-median">—</strong></div>
        <div class="kpi"><span>Maximum province</span><strong id="hz-kpi-max">—</strong></div>
        <div class="kpi"><span>Selected province</span><strong id="hz-kpi-selected">—</strong></div>
        <div class="kpi"><span>Selected P05–P95</span><strong id="hz-kpi-range">—</strong></div>
      </div>
      <div class="card"><div class="card-head"><h3>Provincial high-WBGT days</h3><span id="hz-scale-note" class="hint"></span></div><div id="hz-map" class="plot"></div></div>
      <div class="grid2"><div class="card"><div id="hz-rank" class="plot small"></div></div><div class="card"><div id="hz-profile" class="plot small"></div></div></div>
      <div class="card table-card"><h3>Highest provincial values under current filters</h3><div class="table-wrap"><table id="hz-table"></table></div></div>`;
    const anchor=document.getElementById("workforce")||document.getElementById("uncertainty");
    if(anchor?.parentNode)anchor.parentNode.insertBefore(section,anchor);else document.querySelector("main.shell")?.appendChild(section);
    btn.addEventListener("click",()=>{document.querySelectorAll(".tab").forEach(x=>x.classList.remove("active"));btn.classList.add("active");document.querySelectorAll(".view").forEach(x=>x.classList.add("hidden"));section.classList.remove("hidden");renderAll();});
  }
  function initControls(){
    el("hz-period").innerHTML=PERIODS.map((x,i)=>`<option value="${i}">${x[1]}</option>`).join("");el("hz-period").value="3";
    el("hz-context").innerHTML=Object.entries(CONTEXTS).map(([k,v])=>`<option value="${k}">${v}</option>`).join("");el("hz-context").value="WBGT_od";
    el("hz-threshold").innerHTML=THRESHOLDS.map(x=>`<option value="${x}">WBGT &gt; ${x}°C</option>`).join("");el("hz-threshold").value="27";
    el("hz-province").innerHTML=provinces.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join("");
    const milan=provinces.find(x=>String(x[1]).toLowerCase()==="milano");if(milan)el("hz-province").value=milan[0];
    ["hz-period","hz-context","hz-threshold","hz-outcome","hz-province","hz-color"].forEach(id=>el(id).addEventListener("change",renderAll));
  }
  function spec(){return el("hz-outcome").value==="delta"?{key:"delta",p05:"delta05",p95:"delta95",label:"Additional days/year vs 2006–2025"}:{key:"abs",p05:"abs05",p95:"abs95",label:"Days/year above threshold"};}
  function filtered(pi=null){const p=pi==null?Number(el("hz-period").value):Number(pi),c=el("hz-context").value,t=Number(el("hz-threshold").value);return records.filter(x=>x.pi===p&&x.c===c&&x.t===t);}
  function fixedValues(){const s=spec(),c=el("hz-context").value,t=Number(el("hz-threshold").value);return records.filter(x=>x.c===c&&x.t===t).map(x=>x[s.key]);}
  function renderKpis(rows,s){const vals=rows.map(x=>x[s.key]).filter(Number.isFinite),med=percentile(vals,.5),maxRow=[...rows].sort((a,b)=>b[s.key]-a[s.key])[0],selected=rows.find(x=>x.r===el("hz-province").value);el("hz-kpi-median").textContent=`${f(med,1)} days/yr`;el("hz-kpi-max").textContent=maxRow?`${f(maxRow[s.key],1)} · ${maxRow.pn}`:"—";el("hz-kpi-selected").textContent=selected?`${f(selected[s.key],1)} days/yr`:"—";el("hz-kpi-range").textContent=selected?`${f(selected[s.p05],1)}–${f(selected[s.p95],1)}`:"—";}
  function renderMap(rows,s){const vals=rows.map(x=>x[s.key]),mode=el("hz-color").value,[zmin,zmax]=bounds(vals,mode,mode==="fixed"?fixedValues():null),hasNegative=zmin<-.05;const trace={type:"choropleth",geojson:hzGeo,featureidkey:"properties.REF_AREA",locations:rows.map(x=>x.r),z:rows.map(x=>x[s.key]),zmin,zmax,zauto:false,text:rows.map(x=>x.pn),marker:{line:{color:"#fff",width:.7}},colorscale:hasNegative?DIVERGING_SCALE:IMPACT_SCALE,colorbar:{title:s.label},customdata:rows.map(x=>[x[s.p05],x[s.p95],x.abs,x.delta]),hovertemplate:`<b>%{text}</b><br>${s.label}: %{z:.2f}<br>P05–P95: %{customdata[0]:.2f}–%{customdata[1]:.2f}<br>Absolute: %{customdata[2]:.2f} days/yr<br>Change vs P1: %{customdata[3]:.2f} days/yr<extra></extra>`};if(hasNegative)trace.zmid=0;Plotly.react("hz-map",[trace],{geo:{fitbounds:"locations",visible:false,landcolor:"#f1f3f5",showland:true},margin:{l:0,r:0,t:10,b:0}},{responsive:true,displaylogo:false});el("hz-scale-note").textContent=`${mode==="adaptive"?"5th–95th percentile":mode==="fixed"?"fixed across P1–P4":"visible min–max"} · higher hazard = darker red`;}
  function renderRank(rows,s){const top=[...rows].sort((a,b)=>b[s.key]-a[s.key]).slice(0,15).reverse();Plotly.react("hz-rank",[{type:"bar",orientation:"h",x:top.map(x=>x[s.key]),y:top.map(x=>x.pn),marker:{color:"#d7301f"},customdata:top.map(x=>[x[s.p05],x[s.p95]]),hovertemplate:`<b>%{y}</b><br>${s.label}: %{x:.2f}<br>P05–P95: %{customdata[0]:.2f}–%{customdata[1]:.2f}<extra></extra>`}],{title:{text:"Highest provincial hazard",font:{size:16}},xaxis:{title:s.label},margin:{l:110,r:20,t:55,b:60},plot_bgcolor:"#fff"},{responsive:true,displaylogo:false});}
  function renderProfile(){const r=el("hz-province").value,c=el("hz-context").value,s=spec(),provinceName=provinces.find(x=>x[0]===r)?.[1]||r,colors={25:"#fee8c8",26:"#fdbb84",27:"#e34a33",28:"#b30000"},traces=[];for(const t of THRESHOLDS){const a=records.filter(x=>x.r===r&&x.c===c&&x.t===t).sort((x,y)=>x.pi-y.pi);traces.push({type:"scatter",mode:"lines+markers",name:`>${t}°C`,x:a.map(x=>`P${x.pi+1}`),y:a.map(x=>x[s.key]),line:{color:colors[t],width:t===Number(el("hz-threshold").value)?4:2},marker:{size:t===Number(el("hz-threshold").value)?8:6},customdata:a.map(x=>[x[s.p05],x[s.p95],PERIODS[x.pi][1]]),hovertemplate:`<b>${provinceName}</b><br>%{customdata[2]}<br>WBGT > ${t}°C: %{y:.2f}<br>P05–P95: %{customdata[0]:.2f}–%{customdata[1]:.2f}<extra></extra>`});}Plotly.react("hz-profile",traces,{title:{text:`${provinceName} · threshold profile`,font:{size:16}},yaxis:{title:s.label},xaxis:{title:el("hz-outcome").value==="delta"?"P1 = baseline; P2–P4 = paired change":"Climate period"},margin:{l:65,r:20,t:55,b:65},legend:{orientation:"h",y:-.25},plot_bgcolor:"#fff"},{responsive:true,displaylogo:false});}
  function renderTable(rows,s){const top=[...rows].sort((a,b)=>b[s.key]-a[s.key]).slice(0,20);el("hz-table").innerHTML=`<thead><tr><th>Province</th><th>Mean</th><th>P05</th><th>P95</th><th>Absolute days/yr</th><th>Change vs P1</th></tr></thead><tbody>${top.map(x=>`<tr><td>${x.pn}</td><td>${f(x[s.key],2)}</td><td>${f(x[s.p05],2)}</td><td>${f(x[s.p95],2)}</td><td>${f(x.abs,2)}</td><td>${f(x.delta,2)}</td></tr>`).join("")}</tbody>`;}
  function renderAll(){if(!document.getElementById("hazard"))return;try{const rows=filtered(),s=spec();renderKpis(rows,s);renderMap(rows,s);renderRank(rows,s);renderProfile();renderTable(rows,s);}catch(err){console.error("Climate hazard render failed",err);}}
  async function init(){try{const [g,payload]=await Promise.all([fetchJson(GEO_URL),loadPayload()]);hzGeo=g;const q=payload.q||[],p=payload.m?.p||PERIODS,c=payload.m?.c||[["WBGT_id","Indoor / shade proxy"],["WBGT_od","Direct-sun proxy"]];const cn=c.map(x=>x[0]);records=(payload.r||[]).map(x=>({pi:Number(x[0]),r:String(q[x[1]][0]),pn:displayProvince(q[x[1]][1]),c:cn[x[2]],t:Number(x[3]),abs:n(x[4]),abs05:n(x[5]),abs95:n(x[6]),delta:n(x[7]),delta05:n(x[8]),delta95:n(x[9])}));provinces=q.map(x=>[String(x[0]),displayProvince(x[1])]).sort((a,b)=>a[1].localeCompare(b[1]));if(provinces.length!==103||records.length!==3296)console.warn("Unexpected climate hazard coverage",{provinces:provinces.length,records:records.length});addUi();initControls();renderAll();console.info("Climate hazard module loaded",{provinces:provinces.length,records:records.length,runs:payload.m?.n||10,thresholds:payload.m?.t||THRESHOLDS});}catch(err){console.error("Climate hazard module not loaded",err);}}
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init,{once:true});else init();
})();
